#!/usr/bin/env bash
# gen_camera_unify.sh -- regenerate packages/simulation/camera_unify_mod.c (+ its host header) from PARENA.
#
# BACKLOG SECTION 636 (UNIFY-0/4), "ALL PARENA FIRST, MODS FIRST": the camera decisions -- WoW-style wheel zoom
# (first person at full zoom-in), client-side click-to-move, third-person follow options -- live in
# PARENA/stdlib/camera/{ease,zoom_cam_mod,click_move_mod,camera_follow_mod}.prn. This repo's host C only reads
# input, owns floats/matrices/rendering and calls the exported functions. Do not edit the generated C by hand.
# SHANKPIT carries a byte-identical copy (scripts/gen_camera_unify_rules.sh there) so both games zoom the same way.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
parena_dir="${PARENA_DIR:-$root/../PARENA}"
if [ -x "$parena_dir/.parena-bootstrap" ]; then
    parena_bin="$parena_dir/.parena-bootstrap"
elif [ -x "$parena_dir/parena" ]; then
    parena_bin="$parena_dir/parena"
else
    (cd "$parena_dir" && make .parena-bootstrap >/dev/null)
    parena_bin="$parena_dir/.parena-bootstrap"
fi
out="$root/packages/simulation/camera_unify_mod.c"
hdr="$root/packages/simulation/camera_unify_mod_host.h"
cam="$parena_dir/stdlib/camera"
"$parena_bin" build "$cam/ease.prn" "$cam/zoom_cam_mod.prn" "$cam/click_move_mod.prn" "$cam/camera_follow_mod.prn" -o "$out"
{
    echo '/* camera_unify_mod_host.h -- GENERATED by scripts/gen_camera_unify.sh from camera_unify_mod.c; do not edit.'
    echo ' * Extern declarations for the PARENA camera mods (stdlib/camera, four .prn files). Pure logic, no host callbacks:'
    echo ' * the host calls these, they never call back. ABI: all int, fixed point (milli/permille/mdeg/ms), see'
    echo ' * the header comments of PARENA/stdlib/camera .prn files. */'
    echo '#ifndef CAMERA_UNIFY_MOD_HOST_H'
    echo '#define CAMERA_UNIFY_MOD_HOST_H'
    echo
    grep -E '^int [a-z0-9_]+\(.*\);$' "$out" | sed -E 's/\(\);$/(void);/' | sed 's/^/extern /'
    echo
    echo '#endif /* CAMERA_UNIFY_MOD_HOST_H */'
} > "$hdr"
echo "regenerated $out and $hdr"
